WITH RecentDepartments AS (SELECT *, SUBSTRING(dept_name, 1, 2) AS dept_name_prefix FROM departments WHERE location != 'New York' AND budget >= 1292000 AND budget BETWEEN 1576000 AND 2706000), dept_name_summary AS (SELECT dept_name, ROUND(AVG(budget), 2) AS avg_budget, SUM(CASE WHEN dept_name = 'Legal' THEN 1 ELSE 0 END) AS legal_count FROM RecentDepartments GROUP BY dept_name) SELECT * FROM dept_name_summary WHERE legal_count > 79 ORDER BY dept_name;
